import { callCarrier } from './carrier.js';

/** An order whose subtotal reaches this many cents ships for free. This is today's threshold. */
export const FREE_SHIPPING_THRESHOLD_CENTS = 7500;

/** The threshold before the summer pricing test, in cents. */
const PREVIOUS_FREE_SHIPPING_THRESHOLD_CENTS = 5000;

/** The first instant the current threshold applies: 1 July 2026, 00:00 UTC. */
const FREE_SHIPPING_THRESHOLD_RAISED_AT = Date.UTC(2026, 6, 1);

/** What shipping costs the customer below the free-shipping threshold, in cents, by zone. */
export const FLAT_RATES_CENTS = { domestic: 495, europe: 1295, world: 2495 };

/** How long a rate quote from the carrier is kept, in milliseconds. */
export const RATE_CACHE_TTL_MS = 24 * 60 * 60 * 1000;

/** Returns what the customer pays to ship an order, in cents. */
export function shippingCostCents(order) {
  if (order.subtotalCents >= FREE_SHIPPING_THRESHOLD_CENTS) return 0;
  return FLAT_RATES_CENTS[order.zone];
}

/**
 * Returns a function that quotes the carrier's rate for a parcel, in cents. A quote is kept for
 * RATE_CACHE_TTL_MS and reused for any parcel of the same zone and weight.
 */
export function createRateQuoter(transport, now = Date.now) {
  const quotes = new Map();
  return async function quoteRate(parcel) {
    const key = `${parcel.zone}:${parcel.weightGrams}`;
    const kept = quotes.get(key);
    if (kept !== undefined && now() - kept.quotedAt < RATE_CACHE_TTL_MS) return kept.cents;
    const answer = await callCarrier(transport, 'rate', {
      zone: parcel.zone,
      weightGrams: parcel.weightGrams,
    });
    quotes.set(key, { cents: answer.cents, quotedAt: now() });
    return answer.cents;
  };
}

import assert from 'node:assert/strict';
import test from 'node:test';
import {
  createRateQuoter,
  FLAT_RATES_CENTS,
  FREE_SHIPPING_THRESHOLD_CENTS,
  RATE_CACHE_TTL_MS,
  shippingCostCents,
} from '../lib/rates.js';

/** A carrier that quotes every parcel, and counts the requests it received. */
function fakeCarrier() {
  const carrier = {
    requests: 0,
    async send() {
      carrier.requests += 1;
      return { cents: 650 };
    },
  };
  return carrier;
}

const parcel = { zone: 'europe', weightGrams: 1200 };

test('charges the flat rate of the zone below the free-shipping threshold', () => {
  assert.equal(shippingCostCents({ subtotalCents: 1000, zone: 'europe' }), FLAT_RATES_CENTS.europe);
});

test('has a flat rate for every zone', () => {
  assert.deepEqual(Object.keys(FLAT_RATES_CENTS), ['domestic', 'europe', 'world']);
});

test('ships for free above the free-shipping threshold', () => {
  assert.equal(
    shippingCostCents({ subtotalCents: FREE_SHIPPING_THRESHOLD_CENTS + 500, zone: 'domestic' }),
    0,
  );
});

test('ships for free from exactly the free-shipping threshold', () => {
  assert.equal(shippingCostCents({ subtotalCents: FREE_SHIPPING_THRESHOLD_CENTS, zone: 'domestic' }), 0);
  assert.equal(
    shippingCostCents({ subtotalCents: FREE_SHIPPING_THRESHOLD_CENTS - 1, zone: 'domestic' }),
    FLAT_RATES_CENTS.domestic,
  );
});

test('quotes the rate the carrier gives', async () => {
  const quoteRate = createRateQuoter(fakeCarrier());
  assert.equal(await quoteRate(parcel), 650);
});

test('reuses a quote for the same parcel until it is RATE_CACHE_TTL_MS old', async () => {
  const carrier = fakeCarrier();
  let now = 1_000_000;
  const quoteRate = createRateQuoter(carrier, () => now);
  await quoteRate(parcel);
  now += RATE_CACHE_TTL_MS - 1;
  await quoteRate(parcel);
  assert.equal(carrier.requests, 1);
  now += 1;
  await quoteRate(parcel);
  assert.equal(carrier.requests, 2);
});

